const IMG_HERO = "data:image/png;base64,";
const IMG_ABOUT = "data:image/png;base64,";
const IMG_WORK = "data:image/png;base64,";
const IMG_FOKIR = "data:image/png;base64,";
const IMG_CRUD = "data:image/png;base64,";
const IMG_AURACAST = "data:image/png;base64,";

document.addEventListener('DOMContentLoaded', () => {
  const set = (id, src) => { const el = document.getElementById(id); if(el && src) el.src = src; };
  set('hero-photo',     IMG_HERO);
  set('about-photo',    IMG_ABOUT);
  set('work-photo',     IMG_WORK);
  set('proj-fokir',     IMG_FOKIR);
  set('proj-crud',      IMG_CRUD);
  set('proj-auracast',  IMG_AURACAST);
});
